import re, os, glob
base = '/Users/kristinarash/DEV/Flint/staging/library/strength-and-conditioning/supertraining--verkhoshansky/'
scope = [l.strip() for l in open('/Users/kristinarash/DEV/Flint/staging/_scope_supertraining_ch9a.txt') if l.strip()]
roots = ['/Users/kristinarash/DEV/Flint/staging/library', '/Users/kristinarash/SecondBrain']
names = set()
paths = set()
for r in roots:
    for p in glob.glob(r + '/**/*.md', recursive=True):
        names.add(os.path.basename(p)[:-3])
        paths.add(p[:-3])
bad = []
n = 0
for f in scope:
    t = open(base + f).read()
    body = t.split('---', 2)[2]
    for m in re.findall(r'\[\[([^\]|#]+)', t):
        n += 1
        leaf = m.split('/')[-1]
        ok = leaf in names
        if '/' in m:
            ok = any(p.endswith('/' + m) for p in paths)
        if not ok:
            bad.append((f, m))
    # em dashes not in label heading
    for i, line in enumerate(body.split('\n')):
        if '—' in line and not re.match(r'^\*\*[^*]+\*\* — ', line):
            print('EMDASH', f, i)
        if '—' in line and line.count('—') > 1:
            print('MULTI-EMDASH', f, i)
    for lab in ['What it is', 'Why it works', 'When to apply', 'When NOT to apply', 'Example']:
        if f in scope[:17] and not re.search(r'^\*\*' + lab + r'\*\* — ', body, re.M):
            print('MISSING LABEL', f, lab)
print('links checked', n, 'bad', bad)

